using Essco.Application.Inventory;using Essco.Application.Security;using Essco.Domain.Inventory;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;namespace Essco.Web.Pages.Inventory;[Authorize(Policy=Permissions.Warehouse)]public sealed class IndexModel(InventoryService service,InventoryCreationService creation):PageModel{[BindProperty]public CreateInput Input{get;set;}=new();public IReadOnlyCollection<PhysicalInventory>Items{get;private set;}=[];[TempData]public string?StatusMessage{get;set;}public async Task OnGetAsync(CancellationToken t)=>Items=await service.ListAsync(t);public async Task<IActionResult>OnPostCreateAsync(CancellationToken t){var r=await creation.CreateAsync(Input.Title,Input.Comments,t);StatusMessage=r.Succeeded?$"Inventario {r.InventoryId} creado.":r.Error;return RedirectToPage();}public sealed class CreateInput{public string Title{get;set;}="";public string Comments{get;set;}="";}}
